program='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    centers = []
    for r in range(h - 2):
        for c in range(w - 2):
            patch = [grid[y][c:c+3] for y in range(r, r+3)]
            if patch[1][1] == 2 and all(patch[y][x] == 3 for y in range(3) for x in range(3) if (y, x) != (1, 1)):
                centers.append((r + 1, c + 1))

    rows = {r for r, _ in centers}
    cols = {c for _, c in centers}
    # The 2-colored grid lines act as barriers; rays from each marked center
    # follow its row and column, while crossings with other 2-lines get a 1 ring.
    hrails = {r for r, row in enumerate(grid) if sum(v == 2 for v in row) >= max(3, 0.6 * w)}
    vrails = {c for c in range(w) if sum(grid[r][c] == 2 for r in range(h)) >= max(3, 0.6 * h)}
    for r in rows:
        for c in range(w):
            if out[r][c] == 0:
                out[r][c] = 1
    for c in cols:
        for r in range(h):
            if out[r][c] == 0:
                out[r][c] = 1

    original_centers = set(centers)
    intersections = {(r, c) for r in rows for c in vrails} | {(r, c) for r in hrails for c in cols}
    for r, c in intersections:
        if (r, c) in original_centers or grid[r][c] != 2:
            continue
        for y in range(max(0, r-1), min(h, r+2)):
            for x in range(max(0, c-1), min(w, c+2)):
                if (y, x) != (r, c):
                    out[y][x] = 1
    return out
'''
